input.old_string:
SetSchemePages(
    keyboardScheme,
    keyboardSprite,
    "Dark Matter: Genesis — WASD move, mouse look, LMB attack, RMB block, E interact, Shift sprint, Space jump, Ctrl crouch, I inventory, M map, J journal.");

ControlsSchemeDefinition gamepadScheme = LoadOrCreateScheme(GamepadSchemePath, "Controller");
SetSchemePages(
    gamepadScheme,
    gamepadSprite,
    "Controller support is in progress. Current bindings: left stick move, right stick look, South (A) interact, West (X) attack, East (B) block, North (Y) jump, stick press sprint.");

